const crypto = require("crypto");

// Constant-time compare so a wrong token leaks nothing through response timing.
function tokenMatches(presented, expected) {
  const a = Buffer.from(presented);
  const b = Buffer.from(expected);
  return a.length === b.length && crypto.timingSafeEqual(a, b);
}

// Machine callers (e.g. the dashboard script) have no browser session, so admin
// routes also accept a bearer token from REPORTS_API_TOKEN. Unset means the
// bearer path is closed entirely rather than open to any token.
function hasServiceToken(req) {
  const expected = process.env.REPORTS_API_TOKEN;
  if (!expected) return false;
  const header = req.headers.authorization || "";
  const presented = header.startsWith("Bearer ") ? header.slice(7) : "";
  return presented !== "" && tokenMatches(presented, expected);
}

// Session check for admin routes: a signed cookie set by /login.
function requireLogin(req, res, next) {
  if (req.headers.cookie && /session=/.test(req.headers.cookie)) return next();
  if (hasServiceToken(req)) return next();
  res.status(401).json({ error: "login required" });
}
module.exports = { requireLogin };

